from openpyxl import load_workbook

wb = load_workbook('budget.xlsx', data_only=False)
print('SHEETS:', wb.sheetnames)
for name in wb.sheetnames:
    ws = wb[name]
    print(f'--- {name} dims={ws.dimensions} max_row={ws.max_row} max_col={ws.max_column}')
    for row in ws.iter_rows():
        vals = [(c.coordinate, c.value) for c in row if c.value is not None]
        if vals:
            print(vals)

from openpyxl import load_workbook

wb = load_workbook('budget.xlsx', data_only=True)
print('Sheets:', wb.sheetnames)
for name in wb.sheetnames:
    ws = wb[name]
    print(f'\n=== Sheet: {name} | dims={ws.dimensions} ===')
    for row in ws.iter_rows(values_only=True):
        print(row)
    col_totals = {}
    for row in ws.iter_rows(values_only=True):
        for i, v in enumerate(row, 1):
            if isinstance(v, (int, float)):
                col_totals[i] = col_totals.get(i, 0) + v
    print('Column numeric sums:', col_totals)

from openpyxl import load_workbook

wb = load_workbook('budget.xlsx', data_only=True)

grand_total = 0.0
for ws in wb.worksheets:
    rows = list(ws.iter_rows(values_only=True))
    print(f"=== Sheet: {ws.title} ===")
    for idx, row in enumerate(rows, 1):
        print(idx, row)
    for row in rows:
        cells = [c for c in row if c is not None]
        if not cells:
            continue
        first = str(cells[0]).strip().lower()
        if first == 'total' or first.startswith('total'):
            continue
        for c in cells:
            if isinstance(c, (int, float)) and not isinstance(c, bool):
                grand_total += c

print(f"TOTAL EXPENSES: {grand_total:.2f}")

